#include <vector>
#include <algorithm>

class Solution {
public:
    long long kthSmallestProduct(std::vector<int>& nums1, std::vector<int>& nums2, long long k) {
        auto countLE = [&](long long target) -> long long {
            long long total = 0;
            int n2 = nums2.size();
            for (long long x : nums1) {
                if (x > 0) {
                    int l = 0, r = n2;
                    while (l < r) {
                        int mid = l + (r - l) / 2;
                        if (x * nums2[mid] <= target) l = mid + 1;
                        else r = mid;
                    }
                    total += l;
                } else if (x < 0) {
                    int l = 0, r = n2;
                    while (l < r) {
                        int mid = l + (r - l) / 2;
                        if (x * nums2[mid] <= target) r = mid;
                        else l = mid + 1;
                    }
                    total += (n2 - l);
                } else {
                    if (target >= 0) total += n2;
                }
            }
            return total;
        };

        long long low = -1e10, high = 1e10;
        long long ans = high;
        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (countLE(mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public long kthSmallestProduct(int[] nums1, int[] nums2, long k) {
        long low = -10000000000L, high = 10000000000L;
        long ans = high;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (countLE(nums1, nums2, mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
